-- PDCA Compliance · /dashboard/ehs/epi/catalogo (aud8 88/95) · RD-95: "?" nas abas, busca, categoria, campos do card e Importar.
-- ADITIVA: só textos de ajuda novos (erp_ajuda_campo). Não cria/altera tabela, RLS, policy, grant ou dado de cliente.
-- Idempotente (ON CONFLICT (chave) DO NOTHING). Mantém o prefixo epi.catalogo.* já usado na tela (epi.catalogo.inativar_lote).
INSERT INTO public.erp_ajuda_campo (chave, grupo, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum, ordem, rota, vertical, status)
SELECT v.chave, v.grupo, v.rotulo, v.o_que, v.para_que, v.exemplo, v.erro, v.ordem, v.rota, 'compliance', 'publicado'
FROM (VALUES
 ('epi.catalogo.aba_global', 'Catálogo de EPIs', 'Catálogo Global PS', 'Nada a preencher: catálogo de EPIs padrão da PS Gestão, só leitura.', 'Dá uma base pronta de EPIs (com CA, classe e fabricante) para você importar em vez de cadastrar do zero.', 'Importar "Luva nitrílica CA 12345" do global para a sua empresa.', 'Tentar editar um EPI global: importe para "Meus EPIs" e personalize a cópia.', 1, '/dashboard/ehs/epi/catalogo'),
 ('epi.catalogo.aba_meus', 'Catálogo de EPIs', 'Meus EPIs', 'Nada a preencher: os EPIs que a sua empresa criou ou importou (com Editar, CA e Excluir).', 'Separa o seu catálogo do global; é aqui que você mantém CA, validade e vida útil atualizados.', 'Editar o CA de uma luva que acabou de ser renovada.', 'Procurar um EPI importado na aba Global: ele passa a ficar em Meus EPIs.', 2, '/dashboard/ehs/epi/catalogo'),
 ('epi.catalogo.busca', 'Catálogo de EPIs', 'Buscar', 'Digite parte do nome, modelo ou número do CA para filtrar os EPIs.', 'Encontra rápido um EPI numa lista grande sem rolar todos os cards.', 'Digitar "nitril" para achar as luvas nitrílicas.', 'Esperar que a busca procure fora da aba atual: ela filtra só a aba (Global ou Meus).', 3, '/dashboard/ehs/epi/catalogo'),
 ('epi.catalogo.categoria', 'Catálogo de EPIs', 'Categoria', 'Escolha uma categoria para ver só os EPIs daquele tipo, ou "Todas as categorias".', 'Agrupa os EPIs por classe de proteção (mãos, respiratória, auditiva…) para achar o certo mais rápido.', 'Filtrar por "Proteção respiratória" para comparar máscaras.', 'Achar que um EPI sumiu porque há uma categoria selecionada: volte a "Todas".', 4, '/dashboard/ehs/epi/catalogo'),
 ('epi.catalogo.ca', 'Catálogo de EPIs', 'CA', 'Nada a preencher: o número do Certificado de Aprovação (CA) do EPI e a situação (válido, a vencer, vencido).', 'O CA é a prova legal de que o EPI é aprovado pelo MTE; o traço colorido do card acompanha a validade do CA.', 'CA 12345 com situação "CA válido".', 'Usar um EPI com "CA vencido": ele deixa de ser aceito em fiscalização e perde a proteção legal.', 5, '/dashboard/ehs/epi/catalogo'),
 ('epi.catalogo.classe', 'Catálogo de EPIs', 'Classe/Categoria', 'Nada a preencher: a categoria/classe de proteção do EPI (etiqueta no card).', 'Indica contra qual risco o EPI protege, ajudando a escolher o equipamento certo para cada setor.', 'Etiqueta "Proteção das mãos" numa luva.', 'Entregar um EPI de classe errada para o risco do posto (ex.: luva comum onde se exige nitrílica).', 6, '/dashboard/ehs/epi/catalogo'),
 ('epi.catalogo.fabricante', 'Catálogo de EPIs', 'Fabricante', 'Nada a preencher: o fabricante do EPI.', 'Liga o EPI ao fornecedor/CA correto; o mesmo modelo de fabricantes diferentes pode ter CA próprio.', 'Fabricante "Danny" para uma luva nitrílica.', 'Misturar fabricantes no mesmo card: cada EPI do catálogo é de um fabricante/CA.', 7, '/dashboard/ehs/epi/catalogo'),
 ('epi.catalogo.validade', 'Catálogo de EPIs', 'Validade / Vida útil', 'Nada a preencher: a vida útil do EPI (descartável ou nº de meses) e, no CA, a data de validade.', 'Serve para programar trocas e renovação do CA antes de o EPI vencer.', 'Vida útil "12 meses" ou EPI "Descartável".', 'Confundir vida útil do EPI com validade do CA: são coisas diferentes (uso x aprovação legal).', 8, '/dashboard/ehs/epi/catalogo'),
 ('epi.catalogo.importar', 'Catálogo de EPIs', 'Importar para minha empresa', 'Toque em Importar num card do catálogo global para clonar aquele EPI para a sua empresa e poder personalizar.', 'Evita recadastrar do zero: traz nome, CA, classe e fabricante prontos para você só ajustar o que muda.', 'Importar "Protetor auricular CA 999" e depois ajustar a vida útil na sua empresa.', 'Esquecer de escolher a Empresa-alvo antes de importar: o EPI clonado precisa de uma empresa dona.', 9, '/dashboard/ehs/epi/catalogo')
) AS v(chave, grupo, rotulo, o_que, para_que, exemplo, erro, ordem, rota)
WHERE EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'erp_ajuda_campo')
ON CONFLICT (chave) DO NOTHING;
